-- Macqul phase 2. Additive schema; no demo import or destructive reset.
begin;
create schema if not exists app_private;
revoke all on schema app_private from public, anon, authenticated;
create table public.shops (id uuid primary key default gen_random_uuid(), name text not null, revision bigint not null default 0 check (revision>=0), created_at timestamptz not null default now());
create table public.shop_settings (shop_id uuid primary key references public.shops(id), payload jsonb not null check (jsonb_typeof(payload)='object'));
create table public.app_users (id uuid primary key references auth.users(id) on delete restrict, shop_id uuid not null references public.shops(id), payload jsonb not null, name text generated always as (payload->>'name') stored not null, role text generated always as (payload->>'role') stored not null check (role in ('Admin','Staff')), active boolean generated always as ((payload->>'active')::boolean) stored not null, check ((payload->>'id')::uuid=id), unique(shop_id,id), created_at timestamptz not null default now());
create table public.customers (id uuid primary key, shop_id uuid not null references public.shops(id), payload jsonb not null check (jsonb_typeof(payload)='object' and (payload->>'id')::uuid=id), created_at timestamptz not null default now(), unique (shop_id,id), name text generated always as (payload->>'name') stored not null, phone text generated always as (payload->>'phone') stored not null);
create index customers_shop_idx on public.customers(shop_id);
create table public.vendors (id uuid primary key, shop_id uuid not null references public.shops(id), payload jsonb not null check (jsonb_typeof(payload)='object' and (payload->>'id')::uuid=id), created_at timestamptz not null default now(), unique (shop_id,id), name text generated always as (payload->>'name') stored not null, phone text generated always as (payload->>'phone') stored not null);
create index vendors_shop_idx on public.vendors(shop_id);
create table public.parts (id uuid primary key, shop_id uuid not null references public.shops(id), payload jsonb not null check (jsonb_typeof(payload)='object' and (payload->>'id')::uuid=id), created_at timestamptz not null default now(), unique (shop_id,id), name text generated always as (payload->>'name') stored not null, unit_cost_minor bigint generated always as ((payload->>'cost')::bigint) stored not null, check (unit_cost_minor >= 0 and (payload->>'cost')::numeric = unit_cost_minor));
create index parts_shop_idx on public.parts(shop_id);
create table public.repairs (id uuid primary key, shop_id uuid not null references public.shops(id), payload jsonb not null check (jsonb_typeof(payload)='object' and (payload->>'id')::uuid=id), created_at timestamptz not null default now(), unique (shop_id,id), repair_no text generated always as (payload->>'number') stored not null, customer_id uuid generated always as ((payload->>'customerId')::uuid) stored not null, assigned_to uuid generated always as ((payload->>'userId')::uuid) stored not null, handover_by uuid generated always as ((payload->>'handover')::uuid) stored, status text generated always as (payload->>'status') stored not null, total_price_minor bigint generated always as ((payload->>'price')::bigint) stored, check (total_price_minor is null or (total_price_minor >= 0 and (payload->>'price')::numeric = total_price_minor)), check (status in ('Received','Diagnosing','Waiting for Parts','In Progress','Ready for Pickup','Collected','Cancelled','Unrepairable')), unique (shop_id,repair_no), foreign key (shop_id,customer_id) references public.customers(shop_id,id), foreign key (shop_id,assigned_to) references public.app_users(shop_id,id), foreign key (shop_id,handover_by) references public.app_users(shop_id,id));
create index repairs_shop_idx on public.repairs(shop_id);
create table public.purchase_orders (id uuid primary key, shop_id uuid not null references public.shops(id), payload jsonb not null check (jsonb_typeof(payload)='object' and (payload->>'id')::uuid=id), created_at timestamptz not null default now(), unique (shop_id,id), vendor_id uuid generated always as ((payload->>'vendorId')::uuid) stored not null, repair_id uuid generated always as ((payload->>'repairId')::uuid) stored not null, part_id uuid generated always as ((payload->>'partId')::uuid) stored not null, quantity integer generated always as ((payload->>'quantity')::integer) stored not null, unit_cost_minor bigint generated always as ((payload->>'cost')::bigint) stored not null, received integer generated always as ((payload->>'received')::integer) stored not null, returned integer generated always as ((payload->>'returned')::integer) stored not null, check (quantity > 0 and received >= 0 and received <= quantity and returned >= 0 and returned <= received and unit_cost_minor >= 0), check ((payload->>'quantity')::numeric=quantity and (payload->>'cost')::numeric=unit_cost_minor), foreign key (shop_id,vendor_id) references public.vendors(shop_id,id), foreign key (shop_id,repair_id) references public.repairs(shop_id,id), foreign key (shop_id,part_id) references public.parts(shop_id,id));
create index purchase_orders_shop_idx on public.purchase_orders(shop_id);
create table public.purchase_items (id uuid primary key, shop_id uuid not null references public.shops(id), payload jsonb not null check (jsonb_typeof(payload)='object' and (payload->>'id')::uuid=id), created_at timestamptz not null default now(), unique (shop_id,id), order_id uuid generated always as ((payload->>'orderId')::uuid) stored not null, part_id uuid generated always as ((payload->>'partId')::uuid) stored not null, quantity integer generated always as ((payload->>'quantity')::integer) stored not null, unit_cost_minor bigint generated always as ((payload->>'cost')::bigint) stored not null, check (quantity > 0 and unit_cost_minor >= 0), foreign key (shop_id,order_id) references public.purchase_orders(shop_id,id), foreign key (shop_id,part_id) references public.parts(shop_id,id));
create index purchase_items_shop_idx on public.purchase_items(shop_id);
create table public.repair_part_usage (id uuid primary key, shop_id uuid not null references public.shops(id), payload jsonb not null check (jsonb_typeof(payload)='object' and (payload->>'id')::uuid=id), created_at timestamptz not null default now(), unique (shop_id,id), order_id uuid generated always as ((payload->>'orderId')::uuid) stored not null, repair_id uuid generated always as ((payload->>'repairId')::uuid) stored not null, quantity integer generated always as ((payload->>'quantity')::integer) stored not null, unit_cost_minor bigint generated always as ((payload->>'cost')::bigint) stored not null, check (quantity > 0 and unit_cost_minor >= 0 and (payload->>'quantity')::numeric=quantity and (payload->>'cost')::numeric=unit_cost_minor), foreign key (shop_id,order_id) references public.purchase_orders(shop_id,id), foreign key (shop_id,repair_id) references public.repairs(shop_id,id));
create index repair_part_usage_shop_idx on public.repair_part_usage(shop_id);
create table public.customer_payments (id uuid primary key, shop_id uuid not null references public.shops(id), payload jsonb not null check (jsonb_typeof(payload)='object' and (payload->>'id')::uuid=id), created_at timestamptz not null default now(), unique (shop_id,id), repair_id uuid generated always as ((payload->>'targetId')::uuid) stored not null, recorded_by uuid generated always as ((payload->>'userId')::uuid) stored not null, original_id uuid generated always as ((payload->>'originalId')::uuid) stored, amount_minor bigint generated always as ((payload->>'amount')::bigint) stored not null, check (amount_minor <> 0 and (payload->>'amount')::numeric=amount_minor), check ((amount_minor > 0 and original_id is null) or (amount_minor < 0 and original_id is not null and length(trim(payload->>'notes'))>0)), foreign key (shop_id,repair_id) references public.repairs(shop_id,id), foreign key (shop_id,recorded_by) references public.app_users(shop_id,id), foreign key (shop_id,original_id) references public.customer_payments(shop_id,id) deferrable initially deferred);
create index customer_payments_shop_idx on public.customer_payments(shop_id);
create table public.vendor_payments (id uuid primary key, shop_id uuid not null references public.shops(id), payload jsonb not null check (jsonb_typeof(payload)='object' and (payload->>'id')::uuid=id), created_at timestamptz not null default now(), unique (shop_id,id), vendor_id uuid generated always as ((payload->>'targetId')::uuid) stored not null, order_id uuid generated always as ((payload->>'orderId')::uuid) stored not null, recorded_by uuid generated always as ((payload->>'userId')::uuid) stored not null, original_id uuid generated always as ((payload->>'originalId')::uuid) stored, amount_minor bigint generated always as ((payload->>'amount')::bigint) stored not null, check (amount_minor <> 0 and (payload->>'amount')::numeric=amount_minor), check ((amount_minor > 0 and original_id is null) or (amount_minor < 0 and original_id is not null and length(trim(payload->>'notes'))>0)), foreign key (shop_id,vendor_id) references public.vendors(shop_id,id), foreign key (shop_id,order_id) references public.purchase_orders(shop_id,id), foreign key (shop_id,recorded_by) references public.app_users(shop_id,id), foreign key (shop_id,original_id) references public.vendor_payments(shop_id,id) deferrable initially deferred);
create index vendor_payments_shop_idx on public.vendor_payments(shop_id);
create table public.expenses (id uuid primary key, shop_id uuid not null references public.shops(id), payload jsonb not null check (jsonb_typeof(payload)='object' and (payload->>'id')::uuid=id), created_at timestamptz not null default now(), unique (shop_id,id), amount_minor bigint generated always as ((payload->>'amount')::bigint) stored not null, category text generated always as (payload->>'category') stored not null, check (amount_minor > 0 and (payload->>'amount')::numeric=amount_minor));
create index expenses_shop_idx on public.expenses(shop_id);
create table public.repair_status_history (id uuid primary key, shop_id uuid not null references public.shops(id), payload jsonb not null check (jsonb_typeof(payload)='object' and (payload->>'id')::uuid=id), created_at timestamptz not null default now(), unique (shop_id,id), repair_id uuid generated always as ((payload->>'repairId')::uuid) stored not null, recorded_by uuid generated always as ((payload->>'userId')::uuid) stored not null, foreign key (shop_id,repair_id) references public.repairs(shop_id,id), foreign key (shop_id,recorded_by) references public.app_users(shop_id,id));
create index repair_status_history_shop_idx on public.repair_status_history(shop_id);
create table public.stock_movements (id uuid primary key, shop_id uuid not null references public.shops(id), payload jsonb not null check (jsonb_typeof(payload)='object' and (payload->>'id')::uuid=id), created_at timestamptz not null default now(), unique (shop_id,id), order_id uuid generated always as ((payload->>'orderId')::uuid) stored not null, quantity integer generated always as ((payload->>'quantity')::integer) stored not null, kind text generated always as (payload->>'kind') stored not null, check (quantity > 0 and kind in ('receive','assign','return')), foreign key (shop_id,order_id) references public.purchase_orders(shop_id,id));
create index stock_movements_shop_idx on public.stock_movements(shop_id);
create table public.activity_logs (id uuid primary key, shop_id uuid not null references public.shops(id), payload jsonb not null check (jsonb_typeof(payload)='object' and (payload->>'id')::uuid=id), created_at timestamptz not null default now(), unique (shop_id,id), recorded_by uuid generated always as ((payload->>'userId')::uuid) stored not null, action text generated always as (payload->>'action') stored not null, foreign key (shop_id,recorded_by) references public.app_users(shop_id,id));
create index activity_logs_shop_idx on public.activity_logs(shop_id);
create table app_private.mutation_receipts (shop_id uuid not null references public.shops(id), request_id uuid not null, actor_id uuid not null references public.app_users(id), request_hash text not null, revision bigint not null, created_at timestamptz not null default now(), primary key(shop_id,request_id));
alter table app_private.mutation_receipts enable row level security;
create function public.is_shop_member(p_shop uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.app_users u where u.shop_id=p_shop and u.id=(select auth.uid()) and u.active); $$;
revoke all on function public.is_shop_member(uuid) from public, anon;
grant execute on function public.is_shop_member(uuid) to authenticated;
alter table public.shops enable row level security;
revoke all on public.shops from anon, authenticated;
grant select on public.shops to authenticated;
grant all on public.shops to service_role;
create policy member_read on public.shops for select to authenticated using (public.is_shop_member(id));
alter table public.shop_settings enable row level security;
revoke all on public.shop_settings from anon, authenticated;
grant select on public.shop_settings to authenticated;
grant all on public.shop_settings to service_role;
create policy member_read on public.shop_settings for select to authenticated using (public.is_shop_member(shop_id));
